#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Operation: split into A=[0,x), B=[x,n-y), C=[n-y,n) -> new = C + B + A
    auto doOp = [&](int x, int y) {
        // x>0, y>0, x+y<n
        vector<int> np;
        for(int i = n-y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n-y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x, y});
    };

    for(int k = 0; k < n-1; k++){
        // Find where value k+1 is
        int pos = -1;
        for(int i = 0; i < n; i++) if(p[i] == k+1){ pos = i; break; }
        if(pos == k) continue;

        // Step 1: Move element at pos to position 0
        if(pos > 0 && pos < n-1){
            // x=pos, y=1 => valid if pos+1<n, i.e. pos<n-1
            // New: C=a[n-1], B=a[pos..n-2], A=a[0..pos-1]
            // Element at pos goes to position 1. 
            // Actually: element at pos is first of B, placed at index 1.
            // We want it at 0. Let's use y = n-pos:
            // x=1, y=n-pos => x+y=n-pos+1. Need <n => pos>1
            // New: C=a[pos..n-1], B=a[1..pos-1], A=a[0]
            // Element at pos -> index 0. 
            if(pos > 1){
                doOp(1, n - pos);
                pos = 0;
            } else {
                // pos==1: x=1, y=1 if n>2
                if(n > 2){ doOp(1, 1); pos = n-1; }
                // now at n-1, use x=1, y=1 again... let's just bring to 0 differently
                if(pos == n-1 && n > 2){ doOp(1, n-1-0); /* x=1,y=n-1, x+y=n invalid */ }
                // pos=1: x=pos, y=n-1-pos=n-2, x+y=n-1<n
                pos = 1;
                doOp(1, n-2);
                pos = n-2; // element goes to index n-2? Let me recalc
                // Ugh, let me just recompute pos
                for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;}
            }
        } else if(pos == n-1){
            doOp(1, 1); // brings last to front
            pos = 0;
        }
        if(pos == 0 && k > 0){
            // Move from 0 to k: x=k, y=n-k => x+y=n, invalid. 
            // x=k, y=n-k-1 => new: a[k+1..n-1] + a[k..k] + a[0..k-1]. Element at 0 -> index n-1.
            // Then x=n-1-k, y=k+1 => x+y=n, invalid. Try x=1,y=k: elem at n-1 -> ... 
            doOp(n-k, k);
            // C=a[n-k..n-1], B=a[n-k..n-k-1](empty if equal), A=a[0..n-k-1]. elem at 0 in A -> index n-k + ... 
            for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;}
            if(pos!=k && pos>0 && pos<n-1) doOp(1, n-pos);
            for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;}
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
